package blockbranch.client.realistic;
import java.nio.file.*;import java.util.*;import net.minecraft.core.*;import net.minecraft.world.level.block.Blocks;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;import net.minecraft.client.gui.screens.TitleScreen;
/** Clean newly generated native models. This preview has only a copied definition, no edited witness chunks. */
public final class NativeOrdinaryView {
 private static boolean opened,saving;private static volatile boolean posed;private static final int FIRST=Integer.getInteger("blockbranch.nativeOrdinaryViewStart",0);private static volatile int view=FIRST;private static int settled;private static long began;private static volatile BlockPos anchor;private static final List<Object> records=new ArrayList<>();private static final String[] NAMES={"well","portal","shipwreck","warm","cold","deep-cold","deep-warm"};
 private static Path dir(){return Path.of(System.getProperty("blockbranch.nativeOrdinaryViewDir"));}
 public static void register(){if(FIRST>0)try{var previous=com.google.gson.JsonParser.parseString(Files.readString(dir().resolve("views.json"))).getAsJsonArray();for(int i=0;i<FIRST;i++)records.add(previous.get(i));}catch(Exception e){throw new RuntimeException(e);}ServerTickEvents.END_SERVER_TICK.register(server->{if(server.isDedicatedServer()||posed||server.getPlayerList().getPlayers().isEmpty())return;try{
  var rows=com.google.gson.JsonParser.parseString(Files.readString(Path.of(System.getProperty("blockbranch.nativeOrdinaryWitness")))).getAsJsonArray();var row=rows.get(view/2).getAsJsonObject();var site=row.getAsJsonObject("site");var name=NAMES[view/2];int x=site.get("x").getAsInt(),y=site.get("y").getAsInt(),z=site.get("z").getAsInt();var level=server.overworld();var player=server.getPlayerList().getPlayers().getFirst();var source=server.createCommandSourceStack();var commands=server.getCommands();commands.performPrefixedCommand(source,"time set 6000");commands.performPrefixedCommand(source,"weather clear");commands.performPrefixedCommand(source,"gamemode creative "+player.getName().getString());player.getAbilities().flying=true;player.onUpdateAbilities();commands.performPrefixedCommand(source,"effect clear "+player.getName().getString()+" minecraft:night_vision");commands.performPrefixedCommand(source,"effect give "+player.getName().getString()+" minecraft:night_vision 100000 0 true");
  var box=new net.minecraft.world.level.levelgen.structure.BoundingBox(x-3,y-2,z-3,x+3,y+5,z+3);if(view/2>0){var key=view/2==1?net.minecraft.world.level.levelgen.structure.BuiltinStructures.RUINED_PORTAL_DESERT:view/2==2?net.minecraft.world.level.levelgen.structure.BuiltinStructures.SHIPWRECK_BEACHED:(view/2==3||view/2==6)?net.minecraft.world.level.levelgen.structure.BuiltinStructures.OCEAN_RUIN_WARM:net.minecraft.world.level.levelgen.structure.BuiltinStructures.OCEAN_RUIN_COLD;var holder=level.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.STRUCTURE).getOrThrow(key);var chunk=level.getChunk(x>>4,z>>4);var start=level.structureManager().getStartForStructure(holder.value(),chunk);if(start==null||!start.isValid())throw new AssertionError("Native preview start "+name);box=view%2==0||view>=10?start.getPieces().getFirst().getBoundingBox():start.getBoundingBox();}else level.getChunk(x>>4,z>>4);
  var aim=new BlockPos((box.minX()+box.maxX())/2,box.minY()+Math.min(4,box.getYSpan()/2),(box.minZ()+box.maxZ())/2);anchor=aim;double distance=view/2>=3?(view%2==0?14:24):view/2==2?23:12;double cx=aim.getX()+(view%2==0?-distance:distance),cz=aim.getZ()+distance,cy=Math.max(aim.getY()+5,box.maxY()+3);if(view/2==1)cy=Math.max(cy,y+6);if(view/2==2)cy=box.minY()+(view%2==0?12:18);if(view>=10){var oldEye=BlockPos.containing(cx,cy+player.getEyeHeight(),cz);blockbranch.Blockbranch.LOGGER.info("NATIVE_DEEP_OLD_CAMERA {} {}",oldEye,level.getBlockState(oldEye));cx=view%2==0?box.minX()+3:box.maxX()-3;cz=view%2==0?box.minZ()+3:box.maxZ()-3;cy=box.maxY()+7;var eye=BlockPos.containing(cx,cy+player.getEyeHeight(),cz);if(!level.getBlockState(eye).is(Blocks.WATER))throw new AssertionError("Deep inspection camera must be in water "+eye+" "+level.getBlockState(eye));}double dx=aim.getX()+.5-cx,dz=aim.getZ()+.5-cz,dy=aim.getY()+.5-(cy+player.getEyeHeight());double yaw=Math.toDegrees(Math.atan2(-dx,dz)),pitch=Math.toDegrees(Math.atan2(-dy,Math.hypot(dx,dz)));commands.performPrefixedCommand(source,"tp "+player.getName().getString()+" "+cx+" "+cy+" "+cz+" "+yaw+" "+pitch);records.add(Map.of("name",name,"angle",view%2,"camera",List.of(cx,cy,cz),"aim",aim.toShortString(),"bounds",box.toString()));blockbranch.Blockbranch.LOGGER.info("NATIVE_ORDINARY_VIEW_POSED {} {}",name,view%2);posed=true;
 }catch(Throwable t){blockbranch.Blockbranch.LOGGER.error("NATIVE_ORDINARY_VIEW_FAIL",t);try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception ignored){}}});
 ClientTickEvents.END_CLIENT_TICK.register(client->{try{if(opened&&System.nanoTime()-began>900_000_000_000L){Files.writeString(dir().resolve("result.txt"),"FAIL native view timeout");client.stop();return;}if(!opened&&client.gui.screen() instanceof TitleScreen){opened=true;began=System.nanoTime();client.createWorldOpenFlows().openWorld("NativeOrdinaryReview",()->client.gui.setScreen(new TitleScreen()));return;}if(Files.exists(dir().resolve("result.txt"))){client.stop();return;}if(!posed||client.level==null||client.player==null||saving)return;client.options.fov().set(view/2>=3?75:60);if(!client.gui.hud.isHidden())client.gui.hud.toggle();client.gui.toastManager().clear();var area=client.levelRenderer.viewArea();if(area==null)return;boolean ready=false;for(int dy:new int[]{-16,0,16}){var section=area.getRenderSectionAt(anchor.offset(0,dy,0));ready|=section!=null&&section.getSectionMesh().hasRenderableLayers();}if(!ready){settled=0;return;}if(++settled<(view==FIRST&&FIRST>=10?650:view%2==0?180:100))return;saving=true;String file="native-"+NAMES[view/2]+"-"+(view%2+1)+".png";net.minecraft.client.Screenshot.grab(client.gameDirectory,file,client.gameRenderer.mainRenderTarget(),1,message->client.execute(()->{try{if(view<13){view++;posed=false;saving=false;settled=0;}else{Files.writeString(dir().resolve("views.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(records));Files.writeString(dir().resolve("result.txt"),"PASS fourteen clean native views");client.stop();}}catch(Exception e){throw new RuntimeException(e);}}));}catch(Throwable t){try{Files.writeString(dir().resolve("result.txt"),"FAIL "+t);}catch(Exception ignored){}client.stop();}});
 }
}
